from networkx import Graph, girth
import networkx as nx

g = nx.Graph()
for i in range(22):
    for j in range(i+1, 22):
        if len(list(g.neighbors(i))) < 5 and len(list(g.neighbors(j))) < 5:
            g.add_edge(i, j)
            if len(list(g.neighbors(i))) == 5:
                break
print(g.edges())
print(girth(g))
